//! SPIR-V registry of the Vulkan backend. Owner: packages 2 and 3 (SPIR-V registry, generated by build.rs from shaders/vulkan/*.comp).
//!
//! `build.rs` compiles `rust/engine/shaders/vulkan/*.comp` with glslc (variants listed in `variants*.list`) and generates
//! `vulkan_shaders.rs` in `OUT_DIR` with `SHADERS: &[(&str, &[u8])]` (name = output name, bytes = SPIR-V).

include!(concat!(env!("OUT_DIR"), "/vulkan_shaders.rs"));

/// SPIR-V words of the shader `name` (the bytes of the registry copied into 4-byte aligned memory).
pub fn spirv(name: &str) -> Option<Vec<u32>> {
    let bytes = SHADERS.iter().find(|(n, _)| *n == name)?.1;
    Some(bytes.as_chunks::<4>().0.iter().map(|c| u32::from_le_bytes(*c)).collect())
}